			function setGrpParentReset() {
			    
			    var vcGrpParent = app.lookup("grpParent");
			    /*
			     * getChildren API는 부모그룹이 가지고 있는 전체컨트롤 반환(직접하위에 소속된 컨트롤만 가져옵니다)
			     * getAllRecursiveChildren API는 소속된 자식들의 모든 컨트롤을  가져옵니다.
			     */
			    var vaChildCtrl = vcGrpParent.getChildren();
			    
			    vaChildCtrl.forEach(function(ctrl) {
			        // parent 그룹에 있는 컨트롤이 그룹(container)이면 제거   
			        if (ctrl instanceof cpr.controls.Container) {           
			            vcGrpParent.removeChild(ctrl, true); // 컨트롤 객체까지 다제거
			        }
			    });
			}

