			/**
			 * 전월복사버튼 클릭 이벤트
			 */
			function clickBtnCopy(e){
				var btnCopy = e.control;
				var curDate = btnCopy.userData("yearMonth");
				
				var exDate = '';
				var tempDate = new Date(curDate);
				
				tempDate.setFullYear(tempDate.getFullYear(), tempDate.getMonth()-1, tempDate.getDate());	
				
				if(String(tempDate.getFullYear()).slice(-2) == '00'){	//	해당년도 1월에 전월 복사 클릭 시.. 작년
					exDate = Number(String(tempDate.getFullYear()).substr(0,4))-1 + '12';
				}else{
					exDate = tempDate.getFullYear();
				}
				
				//alert(" 전월복사 버튼 클릭 : "+exDate+" => " + curDate);	
				var dmSearch = app.lookup('dmSearch');
				dmSearch.setValue('YEAR_MONTH', curDate);
				dmSearch.setValue('EX_YEAR_MONTH', exDate);
				
			    doSave('subCopyEx');
			}


