			/**
			 * 데이터 저장 서브미션 호출
			 */
			function doSave(param){
				
			    // 저장 서브미션 호출
			    util.Submit.send(app, param+"", function(pbSuccess){
			        if(pbSuccess){
			        	if(param == 'subCopyEx'){
			        		var ret = app.lookup("subCopyEx").getMetadata("msg");
			        		if(ret == '1'){
			        			console.log('전월복사를 성공하였습니다.');
			        		}else if(ret == '0'){
			        			util.Msg.alert(app, "전월복사할 데이터가 없습니다", null, null, "전월복사 안내");
			        			return;
			        		}
			        	}
			            doList();
			            
			        }
			    });
			}
